package com.devopsclassroom.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="entregas_trabalho") public class EntregaTrabalho { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="trabalho_id",nullable=false) private Trabalho trabalho; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="aluno_id",nullable=false) private Usuario aluno; @Column(length=10000) private String conteudo; private Integer pontuacao; @Column(length=2000) private String feedback; @Column(name="enviado_em") private LocalDateTime enviadoEm; @PrePersist protected void onCreate(){enviadoEm=LocalDateTime.now();} public Long getId(){return id;} public void setId(Long v){id=v;} public Trabalho getTrabalho(){return trabalho;} public void setTrabalho(Trabalho v){trabalho=v;} public Usuario getAluno(){return aluno;} public void setAluno(Usuario v){aluno=v;} public String getConteudo(){return conteudo;} public void setConteudo(String v){conteudo=v;} public Integer getPontuacao(){return pontuacao;} public void setPontuacao(Integer v){pontuacao=v;} public String getFeedback(){return feedback;} public void setFeedback(String v){feedback=v;} public LocalDateTime getEnviadoEm(){return enviadoEm;} }
